changeSet.sql:
CREATE TABLE estate_title_documents ( id uuid NOT NULL PRIMARY KEY, tenant_id uuid NOT NULL REFERENCES organizations (id), branch_id uuid REFERENCES branches (id), created_at timestamp(6) with time zone NOT NULL, updated_at timestamp(6) with time zone, created_by varchar(255), updated_by varchar(255), deleted boolean NOT NULL,
estate_id uuid NOT NULL REFERENCES estates (id), file_id uuid NOT NULL REFERENCES stored_files (id), kind varchar(20) NOT NULL,
CONSTRAINT chk_estate_title_documents_kind CHECK (kind IN ('TITLE_DOCUMENT', 'SURVEY_PLAN', 'DEED')) ); CREATE INDEX idx_estate_title_documents_estate ON estate_title_documents (estate_id); CREATE UNIQUE INDEX uq_estate_title_documents_file ON estate_title_documents (file_id); REVOKE DELETE, TRUNCATE ON estate_title_documents FROM ${appDbUsername}; COMMENT ON TABLE estate_title_documents IS 'Title evidence uploaded for an estate, in private storage. Attached to the title only when a submission names it. Never deleted. See AGENTS.md, "Estate titles".';
ALTER TABLE estate_title_documents ENABLE ROW LEVEL SECURITY; ALTER TABLE estate_title_documents FORCE ROW LEVEL SECURITY; CREATE POLICY estate_title_documents_platform ON estate_title_documents FOR ALL USING (current_setting('landvault.platform_scope', true) = 'on') WITH CHECK (current_setting('landvault.platform_scope', true) = 'on'); CREATE POLICY estate_title_documents_tenant ON estate_title_documents FOR ALL USING ( current_setting('landvault.tenant_id', true) IS NOT NULL AND current_setting('landvault.tenant_id', true) != '' AND tenant_id::text = current_setting('landvault.tenant_id', true) AND ( current_setting('landvault.branch_id', true) IS NULL OR current_setting('landvault.branch_id', true) = '' OR branch_id IS NULL OR branch_id::text = current_setting('landvault.branch_id', true) ) ) WITH CHECK ( current_setting('landvault.tenant_id', true) IS NOT NULL AND current_setting('landvault.tenant_id', true) != '' AND tenant_id::text = current_setting('landvault.tenant_id', true) AND ( current_setting('landvault.branch_id', true) IS NULL OR current_setting('landvault.branch_id', true) = '' OR branch_id IS NULL OR branch_id::text = current_setting('landvault.branch_id', true) ) );

ALTER TABLE estate_titles RENAME COLUMN survey_plan_document_id TO survey_plan_file_id;
ALTER TABLE estate_titles RENAME COLUMN deed_document_id TO deed_file_id;
UPDATE estate_titles SET survey_plan_file_id = NULL
    WHERE survey_plan_file_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM stored_files f WHERE f.id = survey_plan_file_id);
UPDATE estate_titles SET deed_file_id = NULL
    WHERE deed_file_id IS NOT NULL
      AND NOT EXISTS (SELECT 1 FROM stored_files f WHERE f.id = deed_file_id);

ALTER TABLE estate_titles
    ADD COLUMN title_document_file_id uuid REFERENCES stored_files (id),
    ADD COLUMN status                 varchar(20),
    ADD COLUMN submitted_at           timestamp(6) with time zone,
    ADD COLUMN submitted_by           uuid REFERENCES users (id),
    ADD COLUMN decided_at             timestamp(6) with time zone,
    ADD COLUMN decided_by             uuid REFERENCES users (id),
    ADD COLUMN verification_source    varchar(32),
    ADD COLUMN decision_note          text,
    ADD CONSTRAINT fk_estate_titles_survey_plan_file FOREIGN KEY (survey_plan_file_id) REFERENCES stored_files (id),
    ADD CONSTRAINT fk_estate_titles_deed_file FOREIGN KEY (deed_file_id) REFERENCES stored_files (id);

UPDATE estate_titles SET status = 'PENDING', submitted_at = created_at;
ALTER TABLE estate_titles ALTER COLUMN status SET NOT NULL;
ALTER TABLE estate_titles ALTER COLUMN submitted_at SET NOT NULL;

ALTER TABLE estate_titles ADD CONSTRAINT chk_estate_titles_status
    CHECK (status IN ('PENDING', 'VERIFIED', 'REJECTED'));
-- Decided exactly when not pending; a verification always says how.
ALTER TABLE estate_titles ADD CONSTRAINT chk_estate_titles_decision
    CHECK ((status = 'PENDING') = (decided_at IS NULL));
ALTER TABLE estate_titles ADD CONSTRAINT chk_estate_titles_source
    CHECK (verification_source IS NULL OR verification_source IN ('MANUAL_REVIEW', 'REGISTRY_SEARCH'));
ALTER TABLE estate_titles ADD CONSTRAINT chk_estate_titles_verified_source
    CHECK (status <> 'VERIFIED' OR verification_source IS NOT NULL);

CREATE INDEX idx_estate_titles_review_queue ON estate_titles (status, submitted_at) WHERE deleted = false;

COMMENT ON COLUMN estate_titles.status IS
    'PENDING: declared by the developer, not yet checked. VERIFIED/REJECTED: decided by HomeTrue (admin.titles.review), never by the developer. Any new submission returns it to PENDING: a verification was of the documents shown then.';
COMMENT ON COLUMN estate_titles.verification_source IS
    'How HomeTrue verified it: MANUAL_REVIEW (a reviewer compared the documents) or REGISTRY_SEARCH (an official search at the land registry). Registry integrations are not built and may not be claimed here.';
COMMENT ON COLUMN estate_titles.survey_plan_file_id IS
    'A private stored file (estate_title_documents, kind SURVEY_PLAN).';

ALTER TABLE estate_verification_checks DROP CONSTRAINT chk_evc_source;
ALTER TABLE estate_verification_checks ADD CONSTRAINT chk_evc_source
    CHECK (verification_source IS NULL
           OR verification_source IN ('MANUAL_REVIEW', 'REGISTRY_SEARCH', 'AGIS', 'QOREID', 'CAC_REGISTRY'));

changeSet.rollback:
ALTER TABLE estate_verification_checks DROP CONSTRAINT chk_evc_source;
ALTER TABLE estate_verification_checks ADD CONSTRAINT chk_evc_source
    CHECK (verification_source IS NULL
           OR verification_source IN ('MANUAL_REVIEW', 'AGIS', 'QOREID', 'CAC_REGISTRY'));

DELETE FROM role_permissions WHERE permission_id IN
    (SELECT id FROM permissions WHERE code = 'admin.titles.review');
DELETE FROM permissions WHERE code = 'admin.titles.review';
